import { Controller, Get, Post, HttpCode, Req } from '@nestjs/common';
import type { Request } from 'express';
import * as checks from '../common/checks';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

type Row = Record<string, any>;

const DOCUMENT_TYPES = ['구매품의', '검수조서', '대금지급', '실사계획', '자산변동'];

const APPROVAL_STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];

// 가정: 결재 결과 중 완료 시각을 남기는 상태
const FINISHED_STATUSES = ['승인', '반려', '회수', '완료'];

const FIND_PURCHASE_SQL = `
  SELECT
    purchase_request_id AS "id",
    asset_inspection_required AS "inspectionRequired"
  FROM purchase_request
  WHERE purchase_request_id = CAST(:id AS bigint)
`;

const FIND_SQL: Record<string, string> = {
  '구매품의': FIND_PURCHASE_SQL,
  '검수조서': FIND_PURCHASE_SQL,
  '실사계획': `
    SELECT
      asset_inspection_plan_id AS "id"
    FROM asset_inspection_plan
    WHERE asset_inspection_plan_id = CAST(:id AS bigint)
  `,
  '자산변동': `
    SELECT
      asset_change_id AS "id"
    FROM asset_change
    WHERE asset_change_id = CAST(:id AS bigint)
  `,
};

// 상신 시 업무 문서에 결재문서를 연결하고 상태를 결재대기로 바꾼다
// 검수조서는 저장할 컬럼이 없어 연결하지 않는다 (todos 참고)
const LINK_SQL: Record<string, string> = {
  '구매품의': `
    UPDATE purchase_request
    SET approval_document_id = CAST(:approvalDocumentId AS bigint),
      approval_status = '결재대기',
      updated_at = now()
    WHERE purchase_request_id = CAST(:id AS bigint)
  `,
  '실사계획': `
    UPDATE asset_inspection_plan
    SET approval_document_id = CAST(:approvalDocumentId AS bigint),
      approval_status = '신청',
      updated_at = now()
    WHERE asset_inspection_plan_id = CAST(:id AS bigint)
  `,
  '자산변동': `
    UPDATE asset_change
    SET approval_document_id = CAST(:approvalDocumentId AS bigint),
      change_status = '결재대기',
      updated_at = now()
    WHERE asset_change_id = CAST(:id AS bigint)
  `,
};

// 결재 결과를 업무 문서 상태에 반영한다
const REFLECT_SQL: Record<string, string> = {
  '구매품의': `
    UPDATE purchase_request
    SET approval_status = :status,
      updated_at = now()
    WHERE purchase_request_id = CAST(:id AS bigint)
  `,
  '실사계획': `
    UPDATE asset_inspection_plan
    SET approval_status = :status,
      updated_at = now()
    WHERE asset_inspection_plan_id = CAST(:id AS bigint)
  `,
  '자산변동': `
    UPDATE asset_change
    SET change_status = :status,
      updated_at = now()
    WHERE asset_change_id = CAST(:id AS bigint)
  `,
};

function idOf(value: unknown): string | null {
  if (typeof value === 'number' && Number.isInteger(value) && value > 0) {
    return String(value);
  }
  if (typeof value === 'string' && /^[0-9]+$/.test(value)) {
    return value;
  }
  return null;
}

// 가정: 실사계획 승인 상태는 신청/승인/승인취소 뿐이라 결재 상태를 이렇게 옮긴다
function businessStatusOf(documentType: string, status: string): string {
  if (documentType !== '실사계획') {
    return status;
  }
  if (status === '승인' || status === '완료') {
    return '승인';
  }
  if (status === '반려' || status === '회수') {
    return '승인취소';
  }
  return '신청';
}

@Controller('api/v1')
export class FnSfr02507Controller {
  @Post('/asset-approvals')
  @HttpCode(200)
  async submitAssetApproval(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자');
    const data = checks.inputOf(req.body);
    const documentType = typeof data['documentType'] === 'string' ? data['documentType'] : '';
    const documentId = idOf(data['documentId']);
    if (!DOCUMENT_TYPES.includes(documentType) || documentId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '문서 유형과 문서 ID를 확인해 주세요.');
    }
    return transaction(async (db) => {
      if (documentType === '대금지급') {
        // TODO: 대금지급 문서를 저장하는 테이블이 없어 상신할 수 없다
        throw new ApiError(400, 'VALIDATION_FAILED', '대금지급 문서는 아직 상신할 수 없습니다.');
      }
      const found = (await db.query(FIND_SQL[documentType], { id: documentId })) as Row[];
      if (found.length === 0) {
        throw new ApiError(404, 'ASSET_DOCUMENT_NOT_FOUND', '상신할 자산 업무 문서를 찾을 수 없습니다.');
      }
      if (documentType === '검수조서' && found[0]['inspectionRequired'] !== true) {
        throw new ApiError(422, 'INSPECTION_REPORT_NOT_USED', '자산검수조서를 사용하지 않아 검수조서를 상신할 수 없습니다.');
      }
      const inApproval = (await db.query(
        `
          SELECT approval_document_id AS "approvalDocumentId"
          FROM approval_document
          WHERE linked_business_type = :documentType
            AND linked_business_id = CAST(:documentId AS bigint)
            AND approval_status IN ('결재대기', '진행중', '보류')
        `,
        { documentType, documentId },
      )) as Row[];
      if (inApproval.length > 0) {
        throw new ApiError(409, 'ASSET_DOCUMENT_IN_APPROVAL', '이미 결재 중인 문서입니다.');
      }
      // 가정: 연계 결재에 쓰는 양식은 사용 중인 연계 결재 양식 중 첫 번째
      const forms = (await db.query(
        `
          SELECT approval_form_id AS "approvalFormId"
          FROM approval_form
          WHERE is_linked_approval = true
            AND use_status = '사용'
          ORDER BY approval_form_id
          LIMIT 1
        `,
        {},
      )) as Row[];
      const drafters = (await db.query(
        `
          SELECT department_id AS "departmentId"
          FROM employee
          WHERE employee_id = CAST(:userId AS bigint)
        `,
        { userId: user.id },
      )) as Row[];
      if (forms.length === 0 || drafters.length === 0 || drafters[0]['departmentId'] === null) {
        throw new ApiError(502, 'APPROVAL_LINK_FAILED', '전자결재 연계에 실패했습니다. 결재 양식 또는 기안 부서를 확인해 주세요.');
      }
      const created = (await db.query(
        `
          INSERT INTO approval_document (
            approval_form_id, drafter_id, drafter_department_id, document_number,
            title, approval_status, is_urgent, is_secret,
            linked_business_type, linked_business_id,
            submitted_at, created_at, updated_at
          )
          VALUES (
            CAST(:formId AS bigint),
            CAST(:userId AS bigint),
            CAST(:departmentId AS bigint),
            'AST-' || to_char(now(), 'YYYYMMDDHH24MISSUS') || '-' || CAST(:documentId AS text),
            :title,
            '결재대기',
            false,
            false,
            :documentType,
            CAST(:documentId AS bigint),
            now(),
            now(),
            now()
          )
          RETURNING
            approval_document_id AS "approvalDocumentId",
            approval_status AS "approvalStatus"
        `,
        {
          formId: String(forms[0]['approvalFormId']),
          userId: user.id,
          departmentId: String(drafters[0]['departmentId']),
          documentId,
          documentType,
          title: documentType + ' 결재 상신 (' + documentId + ')',
        },
      )) as Row[];
      const approvalDocumentId = String(created[0]['approvalDocumentId']);
      const linkSql = LINK_SQL[documentType];
      if (linkSql !== undefined) {
        await db.execute(linkSql, { id: documentId, approvalDocumentId });
      }
      await db.execute(
        `
          INSERT INTO change_history (
            target_type, target_id, change_type, changed_at, changer_id,
            before_content, after_content, created_at, updated_at
          )
          VALUES (
            'approval_document',
            CAST(:approvalDocumentId AS bigint),
            '등록',
            now(),
            CAST(:userId AS bigint),
            NULL,
            :afterContent,
            now(),
            now()
          )
        `,
        {
          approvalDocumentId,
          userId: user.id,
          afterContent: documentType + ' ' + documentId + ' 결재대기',
        },
      );
      return created[0];
    });
  }

  @Get('/asset-approvals/:approvalDocumentId')
  async getAssetApproval(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자', '임직원');
    const approvalDocumentId = idOf(req.params['approvalDocumentId']);
    if (approvalDocumentId === null) {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서 ID가 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = (await db.query(
        `
          SELECT
            approval_document_id AS "approvalDocumentId",
            approval_status AS "approvalStatus",
            completed_at AS "completedAt"
          FROM approval_document
          WHERE approval_document_id = CAST(:approvalDocumentId AS bigint)
        `,
        { approvalDocumentId },
      )) as Row[];
      if (rows.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '결재 문서를 찾을 수 없습니다.');
      }
      return rows[0];
    });
  }

  @Post('/asset-approvals/result')
  @HttpCode(200)
  async receiveAssetApprovalResult(@Req() req: Request) {
    const user = currentUser(req);
    user.require('자산 담당자', '임직원');
    const data = checks.inputOf(req.body);
    const approvalDocumentId = idOf(data['approvalDocumentId']);
    const status = typeof data['approvalStatus'] === 'string' ? data['approvalStatus'] : '';
    if (approvalDocumentId === null || status === '') {
      throw new ApiError(400, 'VALIDATION_FAILED', '결재문서 ID와 결재 상태를 입력해 주세요.');
    }
    if (!APPROVAL_STATUSES.includes(status)) {
      throw new ApiError(422, 'INVALID_APPROVAL_STATUS', '허용되지 않는 결재 상태입니다.');
    }
    return transaction(async (db) => {
      const docs = (await db.query(
        `
          SELECT
            drafter_id AS "drafterId",
            linked_business_type AS "linkedType",
            linked_business_id AS "linkedId"
          FROM approval_document
          WHERE approval_document_id = CAST(:approvalDocumentId AS bigint)
        `,
        { approvalDocumentId },
      )) as Row[];
      if (docs.length === 0) {
        throw new ApiError(404, 'APPROVAL_DOCUMENT_NOT_FOUND', '결재 문서를 찾을 수 없습니다.');
      }
      const doc = docs[0];
      const finished = FINISHED_STATUSES.includes(status);
      await db.execute(
        `
          UPDATE approval_document
          SET approval_status = :status,
            completed_at = CASE WHEN CAST(:finished AS boolean) THEN now() ELSE completed_at END,
            updated_at = now()
          WHERE approval_document_id = CAST(:approvalDocumentId AS bigint)
        `,
        { status, finished: finished ? 'true' : 'false', approvalDocumentId },
      );
      const linkedType = String(doc['linkedType']);
      const businessStatus = businessStatusOf(linkedType, status);
      const reflectSql = REFLECT_SQL[linkedType];
      if (reflectSql !== undefined && doc['linkedId'] !== null) {
        await db.execute(reflectSql, { status: businessStatus, id: String(doc['linkedId']) });
      }
      await db.execute(
        `
          INSERT INTO change_history (
            target_type, target_id, change_type, changed_at, changer_id,
            before_content, after_content, created_at, updated_at
          )
          VALUES (
            'approval_document',
            CAST(:approvalDocumentId AS bigint),
            :changeType,
            now(),
            CAST(:userId AS bigint),
            NULL,
            :afterContent,
            now(),
            now()
          )
        `,
        {
          approvalDocumentId,
          userId: user.id,
          changeType: status === '승인' || status === '완료' ? '승인' : '수정',
          afterContent: linkedType + ' ' + businessStatus,
        },
      );
      await db.execute(
        `
          INSERT INTO notification (
            employee_id, notification_type, event_type, title, summary,
            target_type, target_id, read_yn, occurred_at, created_at, updated_at
          )
          VALUES (
            CAST(:drafterId AS bigint),
            'ALERT',
            '자산결재결과',
            :title,
            :summary,
            'DOCUMENT',
            CAST(:approvalDocumentId AS bigint),
            false,
            now(),
            now(),
            now()
          )
        `,
        {
          drafterId: String(doc['drafterId']),
          approvalDocumentId,
          title: linkedType + ' 결재 결과',
          summary: '결재 상태: ' + status,
        },
      );
      return { businessStatus };
    });
  }
}

