import { useState } from 'react';
import { Badge, Band, DataTable, DateText, Drawer, Field, Form, LookupSelect, NumberInput, Pairs, RefName, Select, Tiles, call } from '../kit';
import type { PageProps, Row } from '../kit';

const TYPES = ['구매품의', '검수조서', '대금지급', '실사계획', '자산변동'];

const TABLES: Record<string, string> = {
  '구매품의': 'purchase_request',
  '검수조서': 'purchase_request',
  '실사계획': 'asset_inspection_plan',
  '자산변동': 'asset_change',
};

const STATUSES = ['기안', '결재대기', '진행중', '승인', '보류', '반려', '회수', '완료'];

const DONE = ['승인', '반려', '회수', '완료'];

export default function FnSfr02507Page({ role, notify }: PageProps) {
  const [items, setItems] = useState<Row[]>([]);
  const [creating, setCreating] = useState(false);
  const [detail, setDetail] = useState<Row | null>(null);
  const [reflecting, setReflecting] = useState<Row | null>(null);
  const [documentType, setDocumentType] = useState('');
  const [documentId, setDocumentId] = useState<number | string>('');
  const [status, setStatus] = useState('');

  const waiting = items.filter((row) => !DONE.includes(String(row.approvalStatus)));

  function closeCreate() {
    setCreating(false);
    setDocumentType('');
    setDocumentId('');
  }

  async function openDetail(row: Row) {
    try {
      const res = await call('GET', '/asset-approvals/' + row.approvalDocumentId, role);
      setDetail({ ...row, ...res });
    } catch (e) {
      notify(e instanceof Error ? e.message : '조회하지 못했습니다.');
    }
  }

  async function submit() {
    if (documentType === '' || documentId === '') {
      throw new Error('문서 유형과 상신할 문서를 입력해 주세요.');
    }
    const res = await call('POST', '/asset-approvals', role, { documentType, documentId });
    setItems([{ ...res, documentType, documentId }, ...items]);
    notify('결재를 상신했습니다.');
    closeCreate();
  }

  async function reflect() {
    if (reflecting === null || status === '') {
      throw new Error('결재 상태를 선택해 주세요.');
    }
    await call('POST', '/asset-approvals/result', role, {
      approvalDocumentId: reflecting.approvalDocumentId,
      approvalStatus: status,
    });
    const id = reflecting.approvalDocumentId;
    setItems(items.map((row) => (row.approvalDocumentId === id ? { ...row, approvalStatus: status } : row)));
    notify('결재 결과를 반영했습니다.');
    setReflecting(null);
    setStatus('');
  }

  function docCell(row: Row) {
    const table = TABLES[String(row.documentType)];
    if (table === undefined) {
      return <Num value={row.documentId} />;
    }
    return <RefName table={table} role={role} value={row.documentId} />;
  }

  const columns = [
    { key: 'documentType', label: '문서 유형' },
    { key: 'documentId', label: '상신할 문서', render: docCell },
    { key: 'approvalDocumentId', label: '결재문서 ID' },
    { key: 'approvalStatus', label: '결재 진행 상태', render: (row: Row) => <Badge value={row.approvalStatus} /> },
    {
      key: 'action',
      label: '처리',
      render: (row: Row) =>
        DONE.includes(String(row.approvalStatus)) ? null : (
          <button
            type="button"
            onClick={(e) => {
              e.stopPropagation();
              setReflecting(row);
            }}
          >
            결과 반영
          </button>
        ),
    },
  ];

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>상신 현황</h2>
        <Tiles
          items={[
            ['상신 건수', items.length],
            ['결재 진행', waiting.length],
            ['결재 종료', items.length - waiting.length],
          ]}
        />
      </section>
      <section className="box span-8">
        <h2>상신 내역</h2>
        <Band total={items.length}>
          <button type="button" onClick={() => setCreating(true)}>
            결재 상신
          </button>
        </Band>
        <DataTable columns={columns} rows={items} onRowClick={openDetail} empty="상신한 문서가 없습니다." />
      </section>
      <section className="box span-4">
        <h2>처리 대기</h2>
        <DataTable
          columns={[
            { key: 'documentType', label: '문서 유형' },
            { key: 'approvalStatus', label: '상태', render: (row: Row) => <Badge value={row.approvalStatus} /> },
          ]}
          rows={waiting}
          onRowClick={openDetail}
          empty="대기 중인 결재가 없습니다."
        />
      </section>
      {creating && (
        <Drawer title="결재 상신" onClose={closeCreate}>
          <Form onSubmit={submit} submit="상신">
            <Field label="문서 유형" required>
              <Select
                value={documentType}
                onChange={(v) => {
                  setDocumentType(v);
                  setDocumentId('');
                }}
                options={TYPES.map((t): [string, string] => [t, t])}
              />
            </Field>
            <Field label="상신할 자산 업무 문서" required>
              {TABLES[documentType] !== undefined ? (
                <LookupSelect table={TABLES[documentType]} role={role} value={documentId} onChange={setDocumentId} />
              ) : (
                <NumberInput value={documentId} onChange={setDocumentId} />
              )}
            </Field>
          </Form>
        </Drawer>
      )}
      {detail !== null && (
        <Drawer title="결재 상태" onClose={() => setDetail(null)}>
          <Pairs
            items={[
              ['문서 유형', String(detail.documentType ?? '')],
              ['결재문서 ID', String(detail.approvalDocumentId)],
              ['결재 진행 상태', <Badge value={detail.approvalStatus} />],
              ['완료 일시', <DateText value={detail.completedAt} time />],
            ]}
          />
        </Drawer>
      )}
      {reflecting !== null && (
        <Drawer title="결재 결과 반영" onClose={() => setReflecting(null)}>
          <Form onSubmit={reflect} submit="반영">
            <Field label="결재 진행 상태" required>
              <Select value={status} onChange={setStatus} options={STATUSES.map((s): [string, string] => [s, s])} />
            </Field>
          </Form>
        </Drawer>
      )}
    </div>
  );
}
